CREATE TABLE "employees" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "username" varchar UNIQUE NOT NULL,
  "password" varchar NOT NULL,
  "role" varchar NOT NULL,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "shifts" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_type" varchar NOT NULL,
  "shift_date" date NOT NULL,
  "submitted_at" timestamp DEFAULT 'now()',
  "section_number" integer NOT NULL,
  "status" varchar DEFAULT 'draft',
  "employee_id" integer NOT NULL
);

CREATE TABLE "section1_istedad" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "nationality" varchar NOT NULL,
  "expected_arrivals" integer DEFAULT 0,
  "expected_departures" integer DEFAULT 0,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "section2_pilgrims" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "nationality" varchar NOT NULL,
  "arrivals_count" integer DEFAULT 0,
  "departures_count" integer DEFAULT 0,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "section2_flights" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "port_type" varchar NOT NULL,
  "arriving_flights" integer DEFAULT 0,
  "departing_flights" integer DEFAULT 0,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "section2_buses" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "port_type" varchar NOT NULL,
  "arriving_buses" integer DEFAULT 0,
  "departing_buses" integer DEFAULT 0,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "section2_timing" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "avg_flight_processing_time" time,
  "avg_bus_processing_time" time,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "section3_rawda" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "total_visitors" integer DEFAULT 0,
  "permits_issued" integer DEFAULT 0,
  "avg_visit_processing_time" time,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "section4_health" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "hospital_visits" integer DEFAULT 0,
  "admitted_cases" integer DEFAULT 0,
  "death_cases" integer DEFAULT 0,
  "patient_cases" integer DEFAULT 0,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "section5_nusuk" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "archive_cards" integer DEFAULT 0,
  "activated_cards" integer DEFAULT 0,
  "total_arrivals" integer DEFAULT 0,
  "unreceived_cards" integer DEFAULT 0,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "section6_sokn" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "bus_count" integer DEFAULT 0,
  "avg_processing_time" time,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "section7_meeqat" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "bus_count" integer DEFAULT 0,
  "avg_processing_time" time,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "violation_types" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name_ar" varchar NOT NULL
);

CREATE TABLE "location_types" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name_ar" varchar NOT NULL
);

CREATE TABLE "responsible_parties" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name_ar" varchar NOT NULL
);

CREATE TABLE "complaint_sources" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name_ar" varchar NOT NULL
);

CREATE TABLE "mahadir" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "report_number" integer UNIQUE NOT NULL,
  "violation_type_id" integer NOT NULL,
  "location_type_id" integer NOT NULL,
  "responsible_party_id" integer NOT NULL,
  "start_time" time,
  "end_time" time,
  "processing_minutes" integer,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE TABLE "complaints" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" integer NOT NULL,
  "case_number" integer UNIQUE NOT NULL,
  "type" varchar NOT NULL,
  "source_party_id" integer NOT NULL,
  "start_time" time,
  "end_time" time,
  "processing_minutes" integer,
  "created_at" timestamp DEFAULT 'now()'
);

CREATE INDEX "idx_mahadir_report_number" ON "mahadir" ("report_number");

CREATE INDEX "idx_mahadir_violation" ON "mahadir" ("violation_type_id");

CREATE INDEX "idx_mahadir_party" ON "mahadir" ("responsible_party_id");

CREATE INDEX "idx_complaints_case_number" ON "complaints" ("case_number");

CREATE INDEX "idx_complaints_source" ON "complaints" ("source_party_id");

COMMENT ON COLUMN "shifts"."shift_type" IS 'صباح | مساء | ليل';

COMMENT ON COLUMN "complaints"."type" IS 'شكوى | بلاغ';

ALTER TABLE "shifts" ADD FOREIGN KEY ("employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "section1_istedad" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "section2_pilgrims" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "section2_flights" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "section2_buses" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "section2_timing" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "section3_rawda" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "section4_health" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "section5_nusuk" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "section6_sokn" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "section7_meeqat" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "mahadir" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "mahadir" ADD FOREIGN KEY ("violation_type_id") REFERENCES "violation_types" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "mahadir" ADD FOREIGN KEY ("location_type_id") REFERENCES "location_types" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "mahadir" ADD FOREIGN KEY ("responsible_party_id") REFERENCES "responsible_parties" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "complaints" ADD FOREIGN KEY ("shift_id") REFERENCES "shifts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "complaints" ADD FOREIGN KEY ("source_party_id") REFERENCES "complaint_sources" ("id") DEFERRABLE INITIALLY IMMEDIATE;
